import { Controller } from "@hotwired/stimulus"

// The big screen of a game (moderate/games/show). Polls the live numbers
// once a second ("Players: 2", "Answers: 1 / 2") and, when the game was moved
// on from somewhere else (a second screen), refreshes the page in place
// (Turbo morphing). The moderator's own buttons re-render the page directly.
//
// The big screen is one or two browsers, so plain polling is cheap, needs no
// WebSocket and catches up by itself after a network hiccup.
const POLL_INTERVAL = 1_000

export default class extends Controller {
  static targets = [ "players", "answers" ]
  static values = { countersUrl: String, version: Number }

  connect() {
    this.running = true
    this.schedule(POLL_INTERVAL)
  }

  disconnect() {
    this.running = false
    clearTimeout(this.timer)
  }

  schedule(delay) {
    clearTimeout(this.timer)
    this.timer = setTimeout(() => this.poll(), delay)
  }

  async poll() {
    try {
      const response = await fetch(this.countersUrlValue, {
        headers: { Accept: "application/json" }, credentials: "same-origin", cache: "no-store"
      })
      if (response.ok) this.update(await response.json())
    } catch (error) {
      // Offline for a moment: try again on the next tick.
    }

    if (this.running) this.schedule(POLL_INTERVAL)
  }

  update({ version, players, answers }) {
    this.playersTargets.forEach((element) => { element.textContent = players })
    this.answersTargets.forEach((element) => { element.textContent = answers })

    if (version !== this.versionValue && this.refreshedFor !== version) {
      this.refreshedFor = version
      window.Turbo.visit(window.location.href, { action: "replace" })
    }
  }

  versionValueChanged() {
    this.refreshedFor = null
  }
}
EOF
cat > app/javascript/controllers/index.js <<'EOF'
// Controllers are imported statically (not lazy-loaded): they are part of the
// module graph, so they are registered before DOMContentLoaded and connected
// before the page's load event. Behaviour like the delete confirmation or the
// in-place saves is therefore in place as soon as the page is usable.
import { application } from "controllers/application"

import AutoSubmitController from "controllers/auto_submit_controller"
import ClipboardController from "controllers/clipboard_controller"
import InlineSaveController from "controllers/inline_save_controller"
import OptionRowsController from "controllers/option_rows_controller"
import PlayController from "controllers/play_controller"
import PreviewController from "controllers/preview_controller"
import ScreenController from "controllers/screen_controller"

application.register("auto-submit", AutoSubmitController)
application.register("clipboard", ClipboardController)
application.register("inline-save", InlineSaveController)
application.register("option-rows", OptionRowsController)
application.register("play", PlayController)
application.register("preview", PreviewController)
application.register("screen", ScreenController)
EOF

